DROP POLICY membership_create ON public.company_members;
CREATE POLICY membership_create ON public.company_members FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND role='ägare' AND EXISTS(SELECT 1 FROM public.companies c WHERE c.id=company_members.company_id AND c.created_by=auth.uid()));
DROP POLICY company_creator_read ON public.companies;
ALTER POLICY company_read ON public.companies USING(id=public.my_company() OR (created_by=auth.uid() AND public.my_company() IS NULL));
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, company_id uuid REFERENCES public.companies(id), display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(display_name) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR company_id=public.my_company());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TRIGGER touch_profile BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.estim_touch();
CREATE FUNCTION public.estim_new_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.estim_new_profile() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER estim_auth_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.estim_new_profile();
INSERT INTO public.profiles(id,display_name) SELECT id,coalesce(raw_user_meta_data->>'display_name','') FROM auth.users ON CONFLICT DO NOTHING;
CREATE FUNCTION public.estim_member_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.profiles SET company_id=NEW.company_id WHERE id=NEW.user_id; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.estim_member_profile() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER estim_membership_profile AFTER INSERT ON public.company_members FOR EACH ROW EXECUTE FUNCTION public.estim_member_profile();
ALTER TABLE public.audit_log ADD COLUMN approved_name text NOT NULL DEFAULT '';
CREATE FUNCTION public.estim_audit_name() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN SELECT display_name INTO NEW.approved_name FROM public.profiles WHERE id=auth.uid(); NEW.approved_name=coalesce(NEW.approved_name,''); RETURN NEW; END $$;
CREATE TRIGGER estim_audit_display_name BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION public.estim_audit_name();
CREATE INDEX profiles_company_idx ON public.profiles(company_id);